def convert_organization(apps, schema_editor):
    """Preserve old priorities and section memberships before dropping their fields."""
    alias = schema_editor.connection.alias
    Tag = apps.get_model('notetaker', 'Tag')
    Task = apps.get_model('notetaker', 'Task')
    Section = apps.get_model('notetaker', 'TaskSection')
    through = Task.tags.through
    sections = {}
    used = set()
    for section in Section.objects.using(alias).order_by('created_at', 'id'):
        name = section.name.strip() or f'Separador {section.pk}'
        tag, _ = Tag.objects.using(alias).get_or_create(name=name)
        if tag.pk in used:
            # Two equally named groups must not collapse into one membership.
            suffix = 1
            while True:
                tag, _ = Tag.objects.using(alias).get_or_create(name=f'{name} ({section.pk}-{suffix})')
                if tag.pk not in used:
                    break
                suffix += 1
        used.add(tag.pk)
        section.tag_id = tag.pk
        section.save(using=alias, update_fields=['tag'])
        sections[section.pk] = tag.pk
    priorities = {value: Tag.objects.using(alias).get_or_create(name=name)[0].pk
                  for value, name in [('high', 'P1'), ('normal', 'P2'), ('low', 'P3')]}
    for task in Task.objects.using(alias).iterator():
        through.objects.using(alias).get_or_create(task_id=task.pk, tag_id=priorities[task.priority])
        if task.section_id in sections:
            through.objects.using(alias).get_or_create(task_id=task.pk, tag_id=sections[task.section_id])


def restore_organization(apps, schema_editor):
    """Restore compatible legacy values while retaining reusable labels."""
    alias = schema_editor.connection.alias
    Task = apps.get_model('notetaker', 'Task')
    Section = apps.get_model('notetaker', 'TaskSection')
    sections = {section.tag_id: section.pk for section in Section.objects.using(alias).all()}
    for task in Task.objects.using(alias).iterator():
        labels = dict(task.tags.using(alias).values_list('id', 'name'))
        task.section_id = next((sections[pk] for pk in labels if pk in sections), None)
        task.priority = next((value for name, value in [('P1', 'high'), ('P2', 'normal'), ('P3', 'low')]
                              if name in labels.values()), 'normal')
        task.save(using=alias, update_fields=['priority', 'section'])


